def existing_tests_keep_their_points(apps, schema_editor):
    """Old tests keep each question's points; their total becomes the sum and the
    pass mark (a percentage until now) is turned into points of that total."""
    Test = apps.get_model('tests_app', 'Test')
    Question = apps.get_model('tests_app', 'Question')
    for test in Test.objects.all():
        total = sum(Question.objects.filter(test=test).exclude(question_type='passage')
                    .values_list('points', flat=True))
        if not total:
            test.passing_score = 50  # empty test: the new defaults (100 points, equal) apply
            test.save(update_fields=['passing_score'])
            continue
        test.equal_points = False
        test.max_score = total
        test.passing_score = round(test.passing_score / 100 * total, 2)
        test.save(update_fields=['equal_points', 'max_score', 'passing_score'])


